using MediatR;using TopLab.Application.Common.Interfaces;using TopLab.Application.Common.Results;using TopLab.Application.Features.CultureResults.Common;using TopLab.Domain.Patients;using TopLab.Domain.Results;using TopLab.Domain.Users;
namespace TopLab.Application.Features.CultureResults.Commands.MarkCultureReportPrinted;
public sealed class MarkCultureReportPrintedCommandHandler:IRequestHandler<MarkCultureReportPrintedCommand,Result>{private readonly IApplicationDbContext _db;private readonly ICurrentUserService _user;private readonly IDateTimeProvider _clock;public MarkCultureReportPrintedCommandHandler(IApplicationDbContext db,ICurrentUserService user,IDateTimeProvider clock){_db=db;_user=user;_clock=clock;}public async Task<Result> Handle(MarkCultureReportPrintedCommand r,CancellationToken ct){var pt=_db.Set<PatientTest>().FirstOrDefault(x=>x.Id.Value==r.PatientTestId);if(pt is null)return Result.Failure(Error.NotFound("التحليل غير موجود"));var patient=_db.Set<Patient>().FirstOrDefault(x=>x.Id.Value==pt.PatientId.Value);if(patient is null||patient.IsDeleted)return Result.Failure(Error.NotFound("المريض غير موجود."));if(!pt.IsReviewed)return Result.Failure(Error.Conflict("لا يمكن طباعة نتيجة غير معتمدة."));var user=_db.Set<User>().FirstOrDefault(x=>x.Id.Value==_user.UserId);if(user is not null&&user.BlockPrintOnRemainingBalance&&!_user.IsAbsolutePermission&&BalanceProbe.Balance(_db,patient.Id.Value)>0)return Result.Failure(Error.Conflict("يوجد رصيد متبقٍ على حساب المريض؛ لا يمكن الطباعة."));try{pt.MarkPrinted(_user.UserId,_clock.UtcNow);}catch(InvalidOperationException e){return Result.Failure(Error.Conflict(e.Message));}await _db.SaveChangesAsync(ct);return Result.Success();}}
